"""
Build the plugin for Claude Code, Codex and Cursor from the files this
repository tests.

    python .github/scripts/skill.py           # write plugin/ and the three marketplaces
    python .github/scripts/skill.py --check   # fail if any generated file differs

One skill folder, `plugin/skills/yait-aichain/`, in the Agent Skills format all
three read (`name` and `description` in `SKILL.md` frontmatter). Each agent
finds it through its own manifest beside it: `.claude-plugin/`, the portable
`plugin.json` Codex reads, `.cursor-plugin/`; and a marketplace at the
repository root that each agent adds by the repository's name.

Nothing in `plugin/` is written by hand. The skill is `SKILL.md` and `llms.txt`,
which the lightness tests bind against the library, plus `recipes.md`: the
twenty reference solutions of the agent-build task set, each of which
passes its task's check in the instrument tests (where that set is present). A skill that drifts from the
library is worse than none — an agent trusts its context over its weights — so
the copy is regenerated and compared in CI rather than kept in step by care.

The held-out sets never reach the plugin: `recipes.md` is rendered from the
tuning set alone, and a test checks that no held-out task appears in it.
"""

from __future__ import annotations

import importlib.util
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PLUGIN = ROOT / "plugin"
SKILL_DIR = PLUGIN / "skills" / "yait-aichain"
MARKETPLACE = ROOT / ".claude-plugin" / "marketplace.json"
CODEX_MARKETPLACE = ROOT / ".agents" / "plugins" / "marketplace.json"
CURSOR_MARKETPLACE = ROOT / ".cursor-plugin" / "marketplace.json"

DESCRIPTION = ("The provider-agnostic AI toolkit for Python — pipelines, fan-outs and "
               "tool-using agents on any model provider.")

RECIPES_POINTER = """
Worked programs are in `recipes.md` next to this file: twenty tasks, each with a
program that solves it. Start from the closest one.
"""


def _version() -> str:
    sys.path.insert(0, str(ROOT))
    import yait_aichain
    return yait_aichain.__version__


def _run_module():
    spec = importlib.util.spec_from_file_location("agent_builds_run_for_skill",
                                                  ROOT / "evals" / "agent_builds" / "run.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def skill_md() -> str:
    text = (ROOT / "SKILL.md").read_text()
    anchor = "`max_steps=`, `VectorDB`, `Embedding(...)`, `LocalTools` — do not exist and\nraise.\n"
    if text.count(anchor) != 1:
        raise SystemExit("SKILL.md changed where the recipes pointer goes; update .github/scripts/skill.py")
    return text.replace(anchor, anchor + RECIPES_POINTER, 1)


def recipes_md() -> str:
    return ("# Recipes for yait-aichain\n\n"
            "Generated by `.github/scripts/skill.py` from the task set the library is measured on.\n"
            "Every program here passes its task's check.\n\n"
            + _run_module().recipes() + "\n")


def plugin_json(version: str) -> str:
    return json.dumps({
        "name": "yait-aichain",
        "version": version,
        "description": DESCRIPTION,
        "author": {"name": "YAIT"},
        "homepage": "https://github.com/yaitio/aichain",
        "repository": "https://github.com/yaitio/aichain",
        "license": "MIT",
        "keywords": ["llm", "agents", "python", "yait-aichain"],
    }, indent=2) + "\n"


def marketplace_json(version: str) -> str:
    return json.dumps({
        "name": "yait",
        "owner": {"name": "YAIT"},
        "plugins": [{
            "name": "yait-aichain",
            "source": "./plugin",
            "description": DESCRIPTION,
            "version": version,
        }],
    }, indent=2) + "\n"


def codex_plugin_json(version: str) -> str:
    # The portable manifest at the plugin root; Codex reads it before its own
    # `.codex-plugin/` overlay, and finds `skills/` without being told.
    return json.dumps({
        "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
        "name": "yait-aichain",
        "version": version,
        "description": DESCRIPTION,
    }, indent=2) + "\n"


def codex_marketplace_json() -> str:
    return json.dumps({
        "name": "yait",
        "interface": {"displayName": "YAIT"},
        "plugins": [{
            "name": "yait-aichain",
            "source": {"source": "local", "path": "./plugin"},
            "policy": {"installation": "AVAILABLE", "authentication": "ON_INSTALL"},
            "category": "Coding",
        }],
    }, indent=2) + "\n"


def cursor_plugin_json(version: str) -> str:
    return json.dumps({
        "name": "yait-aichain",
        "description": DESCRIPTION,
        "version": version,
        "author": {"name": "YAIT"},
    }, indent=2) + "\n"


def cursor_marketplace_json(version: str) -> str:
    return json.dumps({
        "name": "yait",
        "owner": {"name": "YAIT"},
        "metadata": {"description": "Plugins from YAIT", "version": version},
        "plugins": [{
            "name": "yait-aichain",
            "source": "./plugin",
            "description": DESCRIPTION,
        }],
    }, indent=2) + "\n"


def codex_skill_yaml() -> str:
    # Codex reads an optional agents/openai.yaml beside SKILL.md for how the
    # skill is shown; the other agents ignore the folder.
    return ("interface:\n"
            "  display_name: \"yait-aichain\"\n"
            f"  short_description: \"{DESCRIPTION}\"\n"
            "policy:\n"
            "  allow_implicit_invocation: true\n")


#: The task set the recipes are rendered from. It is not part of every
#: checkout; where it is absent, the committed recipes.md stands as it is.
TASKS = ROOT / "evals" / "agent_builds" / "run.py"


def generated() -> dict:
    version = _version()
    return {
        SKILL_DIR / "SKILL.md": skill_md(),
        SKILL_DIR / "llms.txt": (ROOT / "llms.txt").read_text(),
        **({SKILL_DIR / "recipes.md": recipes_md()} if TASKS.exists() else {}),
        SKILL_DIR / "agents" / "openai.yaml": codex_skill_yaml(),
        PLUGIN / ".claude-plugin" / "plugin.json": plugin_json(version),
        MARKETPLACE: marketplace_json(version),
        PLUGIN / "plugin.json": codex_plugin_json(version),
        CODEX_MARKETPLACE: codex_marketplace_json(),
        PLUGIN / ".cursor-plugin" / "plugin.json": cursor_plugin_json(version),
        CURSOR_MARKETPLACE: cursor_marketplace_json(version),
    }


def main(argv=None) -> int:
    check = "--check" in (argv if argv is not None else sys.argv[1:])
    stale = []
    for path, content in generated().items():
        current = path.read_text() if path.exists() else None
        if current == content:
            continue
        if check:
            stale.append(path.relative_to(ROOT).as_posix())
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content)
            print("wrote", path.relative_to(ROOT).as_posix())
    if stale:
        print("stale — run python .github/scripts/skill.py:\n  " + "\n  ".join(stale))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
